### `modules/s3/main.tf` — Fixed count/for_each

```hcl
variable "environment"        { type = string }
variable "app_name"           { type = string }
variable "enable_replication" { type = bool }
variable "replica_region"     { type = string }
variable "eks_node_role_arn"  { type = string }

terraform {
  required_providers {
    aws = {
      source                = "hashicorp/aws"
      configuration_aliases = [aws, aws.replica]
    }
  }
}

locals {
  bucket_name = "${var.app_name}-assets-${var.environment}-${data.aws_caller_identity.current.account_id}"
}

data "aws_caller_identity" "current" {}

# ============================================================
# Primary bucket
# ============================================================
resource "aws_s3_bucket" "assets" {
  bucket = local.bucket_name
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ============================================================
# FIX: Replica bucket uses for_each with variable-driven set,
# NOT count based on a resource attribute.
#
# BEFORE (broken):
#   count = aws_s3_bucket.assets.arn != "" ? 1 : 0
#
# AFTER (fixed):
#   for_each = var.enable_replication ? toset(["replica"]) : toset([])
# ============================================================

resource "aws_s3_bucket" "replica" {
  # ✅ for_each driven by a VARIABLE (known at plan time)
  for_each = var.enable_replication ? toset(["replica"]) : toset([])

  provider = aws.replica
  bucket   = "${local.bucket_name}-replica"
}

resource "aws_s3_bucket_versioning" "replica" {
  for_each = aws_s3_bucket.replica

  provider = aws.replica
  bucket   = each.value.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  for_each = aws_s3_bucket.replica

  provider = aws.replica
  bucket   = each.value.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  for_each = aws_s3_bucket.replica

  provider = aws.replica
  bucket   = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ============================================================
# Replication IAM role — also uses for_each
# ============================================================
resource "aws_iam_role" "replication" {
  for_each = var.enable_replication ? toset(["replication"]) : toset([])

  name = "${var.app_name}-s3-replication-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy" "replication" {
  for_each = aws_iam_role.replication

  name = "s3-replication"
  role = each.value.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [aws_s3_bucket.assets.arn]
      },
      {
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Effect   = "Allow"
        Resource = ["${aws_s3_bucket.assets.arn}/*"]
      },
      {
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Effect   = "Allow"
        Resource = ["${aws_s3_bucket.replica["replica"].arn}/*"]
      }
    ]
  })
}

# ============================================================
# Replication configuration — for_each
# ============================================================
resource "aws_s3_bucket_replication_configuration" "assets" {
  for_each = var.enable_replication ? toset(["enabled"]) : toset([])

  depends_on = [aws_s3_bucket_versioning.assets]

  bucket = aws_s3_bucket.assets.id
  role   = aws_iam_role.replication["replication"].arn

  rule {
    id     = "replicate-all"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.replica["replica"].arn
      storage_class = "STANDARD"
    }
  }
}

# ============================================================
# Outputs
# ============================================================
output "bucket_arn" {
  value = aws_s3_bucket.assets.arn
}

output "bucket_regional_domain_name" {
  value = aws_s3_bucket.assets.bucket_regional_domain_name
}

output "replica_bucket_arn" {
  value = var.enable_replication ? aws_s3_bucket.replica["replica"].arn : null
}
```

---

### `modules/rds/main.tf`

```hcl
variable "environment"          { type = string }
variable "app_name"             { type = string }
variable "instance_class"       { type = string }
variable "multi_az"             { type = bool }
variable "storage_encrypted"    { type = bool }
variable "vpc_id"               { type = string }
variable "db_subnet_group_name" { type = string }
variable "rds_sg_id"            { type = string }
variable "db_password" {
  type      = string
  sensitive = true
}

resource "aws_db_instance" "main" {
  identifier = "${var.app_name}-${var.environment}"

  engine         = "postgres"
  engine_version = "16.3"
  instance_class = var.instance_class

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = var.storage_encrypted

  db_name  = "webapp"
  username = "webapp_admin"
  password = var.db_password

  multi_az               = var.multi_az
  db_subnet_group_name   = var.db_subnet_group_name
  vpc_security_group_ids = [var.rds_sg_id]

  # Acceptance criteria
  deletion_protection      = true
  backup_retention_period  = var.environment == "prod" ? 30 : 7
  publicly_accessible      = false
  skip_final_snapshot      = var.environment == "dev" ? true : false
  final_snapshot_identifier = var.environment == "prod" ? "${var.app_name}-prod-final" : null

  tags = {
    Environment = var.environment
  }
}

output "endpoint" { value = aws_db_instance.main.endpoint }
output "db_name"  { value = aws_db_instance.main.db_name }
```

---

### `modules/iam/main.tf`

```hcl
variable "environment"       { type = string }
variable "app_name"          { type = string }
variable "oidc_provider_arn" { type = string }
variable "oidc_provider_url" { type = string }
variable "s3_bucket_arn"     { type = string }

# ============================================================
# Dev: IAM user with programmatic access
# Prod: IAM role with OIDC trust (IRSA) — least privilege
# ============================================================

# ✅ for_each for conditional IAM user (dev only)
resource "aws_iam_user" "app" {
  for_each = var.environment == "dev" ? toset(["app"]) : toset([])

  name = "${var.app_name}-app-${var.environment}"
}

resource "aws_iam_access_key" "app" {
  for_each = aws_iam_user.app
  user     = each.value.name
}

resource "aws_iam_user_policy" "app_s3" {
  for_each = aws_iam_user.app

  name = "s3-access"
  user = each.value.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = [
        "s3:GetObject",
        "s3:PutObject",
        "s3:ListBucket"
      ]
      Effect = "Allow"
      Resource = [
        var.s3_bucket_arn,
        "${var.s3_bucket_arn}/*"
      ]
    }]
  })
}

# ✅ IAM Role for Service Account (prod — OIDC trust)
resource "aws_iam_role" "app" {
  name = "${var.app_name}-app-${var.environment}"

  assume_role_policy = var.environment == "prod" ? jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRoleWithWebIdentity"
      Effect = "Allow"
      Principal = {
        Federated = var.oidc_provider_arn
      }
      Condition = {
        StringEquals = {
          "${replace(var.oidc_provider_url, "https://", "")}:sub" = "system:serviceaccount:default:${var.app_name}"
          "${replace(var.oidc_provider_url, "https://", "")}:aud" = "sts.amazonaws.com"
        }
      }
    }]
  }) : jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy" "app_s3" {
  name = "s3-access"
  role = aws_iam_role.app.id

  # ✅ Least privilege: no wildcards on prod
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = var.environment == "prod" ? [
        "s3:GetObject",
        "s3:PutObject",
        "s3:ListBucket"
      ] : [
        "s3:GetObject",
        "s3:PutObject",
        "s3:DeleteObject",
        "s3:ListBucket"
      ]
      Effect = "Allow"
      Resource = [
        var.s3_bucket_arn,
        "${var.s3_bucket_arn}/*"
      ]
    }]
  })
}

output "app_role_arn"  { value = aws_iam_role.app.arn }
output "app_user_name" {
  value = var.environment == "dev" ? aws_iam_user.app["app"].name : null
}
