```hcl
variable "environment"       { type = string }
variable "app_name"          { type = string }
variable "enable_cloudfront" { type = bool }
variable "vpc_id"            { type = string }
variable "public_subnet_ids" { type = list(string) }
variable "s3_bucket_domain"  { type = string }

# ============================================================
# Dev: Internal ALB with HTTPS listener
# Prod: CloudFront + ACM cert
# ============================================================

# ✅ for_each for ALB (dev only)
resource "aws_lb" "internal" {
  for_each = var.enable_cloudfront ? toset([]) : toset(["alb"])

  name               = "${var.app_name}-${var.environment}"
  internal           = true
  load_balancer_type = "application"
  subnets            = var.public_subnet_ids

  tags = {
    Environment = var.environment
  }
}

resource "aws_lb_listener" "https" {
  for_each = aws_lb.internal

  load_balancer_arn = each.value.arn
  port              = 443
  protocol          = "HTTPS"

  # No forced 80→443 redirect (per acceptance criteria)

  default_action {
    type = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      status_code  = "200"
      message_body = "OK"
    }
  }
}

# ✅ for_each for CloudFront (prod only)
resource "aws_cloudfront_distribution" "main" {
  for_each = var.enable_cloudfront ? toset(["cdn"]) : toset([])

  enabled = true
  comment = "${var.app_name} ${var.environment}"

  origin {
    domain_name = var.s3_bucket_domain
    origin_id   = "s3"

    s3_origin_config {
      origin_access_identity = ""
    }
  }

  default_cache_behavior {
    target_origin_id       = "s3"
    viewer_protocol_policy = "https-only"
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
      cookies { forward = "none" }
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
    # In real usage, reference an ACM cert:
    # acm_certificate_arn = aws_acm_certificate.main.arn
    # ssl_support_method  = "sni-only"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  tags = {
    Environment = var.environment
  }
}

output "alb_dns_name" {
  value = var.enable_cloudfront ? null : aws_lb.internal["alb"].dns_name
}

output "cloudfront_domain" {
  value = var.enable_cloudfront ? aws_cloudfront_distribution.main["cdn"].domain_name : null
}
